"use strict";

$(document).ready(function () {
  var cmsPageLocator = {
    Init: function Init() {
      this.BindEvents();
    },
    BindEvents: function BindEvents() {
      $(document).keypress(cmsPageLocator.Events.EnableShortCuts);
    },
    Events: {
      EnableShortCuts: function EnableShortCuts(ev) {
        var kCode = ev.keyCode || ev.which; // gets the keycode in ie or ns
        //CTRL+SHIFT+E (EDIT CMS PAGE)

        if (ev.ctrlKey && ev.shiftKey && (kCode === 69 || kCode === 5)) {
          var mEditurl = $("meta[name='cmsurl']").attr("content");

          if (mEditurl != null && mEditurl.length > 0) {
            if (confirm("Edit page?")) {
              mEditurl = mEditurl.replace(/local.dell.com/i, "cmscontent.dell.com");
              var cmsurlQs = $("meta[name='cmsurlqs']").attr("content");

              if (cmsurlQs != null && cmsurlQs.length > 0) {
                if (mEditurl.indexOf("?") > -1) {
                  mEditurl = mEditurl + "&" + cmsurlQs;
                } else {
                  mEditurl = mEditurl + "?" + cmsurlQs;
                }
              }

              window.open(mEditurl, 'cmsEditWin');
            }
          }
        }
      }
    }
  };
  cmsPageLocator.Init();
});
